class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(arr):
    if not arr or arr[0] is None:
        return None
    root = TreeNode(arr[0])
    queue = [root]
    i = 1
    while i < len(arr) and queue:
        node = queue.pop(0)
        if i < len(arr):
            left_val = arr[i]
            i += 1
            if left_val is not None:
                node.left = TreeNode(left_val)
                queue.append(node.left)
        if i < len(arr):
            right_val = arr[i]
            i += 1
            if right_val is not None:
                node.right = TreeNode(right_val)
                queue.append(node.right)
    return root


def is_cousins(root_arr, x, y):
    root = build_tree(root_arr)
    info = {}
    queue = [(root, None, 0)]
    while queue:
        node, parent, depth = queue.pop(0)
        if node.val in (x, y):
            info[node.val] = (parent, depth)
        if node.left:
            queue.append((node.left, node.val, depth + 1))
        if node.right:
            queue.append((node.right, node.val, depth + 1))

    px, dx = info[x]
    py, dy = info[y]
    return dx == dy and px != py

